/* All review data remains in this origin's IndexedDB on the user's device. */
const $=id=>document.getElementById(id),escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let trails=[],view='list',registration,installPrompt,syncing=false;
const map=new TrailMap($('map'),t=>{$('mapDetail').replaceChildren(card(t));});
function status(s){$('status').textContent=s;}
function settingsStatus(s){$('settingsStatus').textContent=s;}
// Capture and remove the fragment before any asynchronous work. Fragments are
// not sent in HTTP requests; review contents are never committed to GitHub.
let pendingImport;
if(location.hash.startsWith('#import=')){
  const raw=location.hash.slice(8);history.replaceState(null,'',location.pathname+location.search);
  try{if(raw.length>100000)throw Error('Import link too large.');pendingImport=JSON.parse(new TextDecoder().decode(Trails.un64(raw.replace(/-/g,'+').replace(/_/g,'/'))));}catch{status('Invalid trail import link.');}
}
async function importLink(){
  if(!pendingImport)return;
  const payload=pendingImport;pendingImport=null;
  if(![1,2].includes(payload.version)||!Array.isArray(payload.trails)||!payload.trails.length||payload.trails.length>100)throw Error('Invalid trail import link.');
  const checked=payload.trails.map(Trails.validate);
  if(!confirm('Save these reviews on this device?\n\n'+checked.map(t=>`${t.city}: ${t.name} · ${t.status==='want-to-go'?'Want to go':t.rating+'/5'}`).join('\n')))return;
  const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(payload)));
  const receiptId='link:'+Trails.b64(digest);let count;
  if(registration?.active){
    const channel=new MessageChannel();count=await new Promise((res,rej)=>{const timer=setTimeout(()=>rej(Error('Import timed out. Reopen the import link to retry.')),15000);channel.port1.onmessage=e=>{clearTimeout(timer);e.data.error?rej(Error(e.data.error)):res(e.data.count);};registration.active.postMessage({type:'IMPORT_LOCAL',payload,receiptId},[channel.port2]);});
  }else count=await Trails.ingest(payload,receiptId);
  await reload();status(count?`${count} reviews saved on this device.`:'These reviews were already imported on this device.');
}
function direction(t){const dest=t.lat!==null?`${t.lat},${t.lon}`:[t.address||t.name,t.city].join(', ');return 'https://maps.apple.com/?daddr='+encodeURIComponent(dest)+'&dirflg=d';}
function card(t){const el=document.createElement('article');el.className='card';el.innerHTML=`<div class="card-top"><span class="badge ${escapeHTML(t.difficulty)}">${escapeHTML(t.difficulty||'Not specified')}</span><span class="rating">${t.status==='want-to-go'?'Want to go':'★ '+String(t.rating)+' <small>/ 5</small>'}</span></div><h3>${escapeHTML(t.name)}</h3><div class="meta">${escapeHTML(t.city)}${t.distance!==null?' · '+escapeHTML(t.distance)+' mi':''}${t.lat===null?' · No map pin':''}</div><p>${escapeHTML(t.description)}</p><div class="card-bottom"><a href="${direction(t)}" target="_blank" rel="noopener">Get directions ↗</a><button class="quiet">Edit notes</button></div>`;el.querySelector('button').onclick=()=>edit(t);return el;}
function filtered(){const query=$('search').value.trim().toLowerCase(),city=$('cityFilter').value,stage=$('statusFilter').value;return trails.filter(t=>(!stage||(t.status||'visited')===stage)&&(!city||t.city===city)&&(!query||[t.name,t.city,t.description,t.address].join(' ').toLowerCase().includes(query))).sort((a,b)=>$('sort').value==='rating'?(b.rating??-1)-(a.rating??-1):$('sort').value==='name'?a.name.localeCompare(b.name):b.updatedAt.localeCompare(a.updatedAt));}
function render(){const list=filtered();$('total').textContent=trails.length;$('results').replaceChildren();$('results').hidden=view==='map';$('mapSection').hidden=view!=='map';$('listBtn').setAttribute('aria-pressed',view==='list');$('mapBtn').setAttribute('aria-pressed',view==='map');
  if(view==='list'){
    if(!list.length){const empty=document.createElement('div');empty.className='empty';empty.innerHTML=`<span class="empty-icon" aria-hidden="true">⌁</span><h3>${trails.length?'No trails found.':'Every great journal starts with a walk.'}</h3><p>${trails.length?'Try another city or a different search.':'Add your first trail and make a little room for your next adventure.'}</p><button class="primary">${trails.length?'Clear filters':'＋ Add your first trail'}</button>`;empty.querySelector('button').onclick=()=>{if(trails.length){$('search').value='';$('cityFilter').value='';$('statusFilter').value='';render();}else edit();};$('results').append(empty);}
    const cities=[...new Set(list.map(t=>t.city))].sort((a,b)=>a.localeCompare(b));for(const city of cities){const group=list.filter(t=>t.city===city),h=document.createElement('h3');h.className='city-heading';h.textContent=city;const c=document.createElement('span');c.textContent=`${group.length} trail${group.length===1?'':'s'}`;h.append(c);const grid=document.createElement('div');grid.className='trail-grid';for(const t of group)grid.append(card(t));$('results').append(h,grid);}
  }else{map.active=true;map.setTrails(list);$('mapDetail').replaceChildren();const missing=list.filter(t=>t.lat===null).length;$('mapNote').textContent=`${list.length-missing} pinned trail${list.length-missing===1?'':'s'}${missing?' · '+missing+' need coordinates (Edit notes)':''}`;}
  if(view!=='map')map.active=false;
}
async function reload(){trails=await Trails.all('trails');const selected=$('cityFilter').value,cities=[...new Set(trails.map(t=>t.city))].sort();$('cityFilter').innerHTML='<option value="">All cities</option>';$('cities').replaceChildren();for(const c of cities){const o=document.createElement('option');o.value=c;o.textContent=c;$('cityFilter').append(o);const d=document.createElement('option');d.value=c;$('cities').append(d);}if(cities.includes(selected))$('cityFilter').value=selected;render();}
function edit(t){$('trailForm').reset();$('trailId').value=t?.id||'';$('editorTitle').textContent=t?'Edit trail':'Add a trail';$('deleteBtn').hidden=!t;$('formError').textContent='';$('geocodeResults').replaceChildren();for(const [field,key] of [['trailName','name'],['trailCity','city'],['rating','rating'],['trailStatus','status'],['difficulty','difficulty'],['description','description'],['distance','distance'],['address','address'],['lat','lat'],['lon','lon']])if(t)$(field).value=t[key]??'';$('trailStatus').value=t?.status||'visited';updateRating();$('editor').showModal();}
function updateRating(){const wanted=$('trailStatus').value==='want-to-go';$('rating').required=!wanted;$('ratingLabel').textContent=wanted?'Your rating (optional; not visited)':'Your rating';}
$('trailStatus').onchange=updateRating;
for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>$(b.dataset.close).close();
$('addBtn').onclick=()=>edit();$('listBtn').onclick=()=>{view='list';render();};$('mapBtn').onclick=()=>{view='map';render();};for(const id of ['search','cityFilter','statusFilter','sort'])$(id).addEventListener(id==='search'?'input':'change',render);
$('zoomIn').onclick=()=>map.changeZoom(1);$('zoomOut').onclick=()=>map.changeZoom(-1);$('fitMap').onclick=()=>map.fit();
$('trailForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const t=Trails.validate({id:$('trailId').value,name:$('trailName').value,city:$('trailCity').value,rating:$('rating').value,status:$('trailStatus').value,difficulty:$('difficulty').value,description:$('description').value,distance:$('distance').value,address:$('address').value,lat:$('lat').value,lon:$('lon').value});await Trails.write('trails',[t]);$('editor').close();await reload();status('Trail saved on this device.');}catch(err){$('formError').textContent=err.message;}finally{b.disabled=false;}};
$('deleteBtn').onclick=async()=>{if(!confirm('Delete this trail from this device?'))return;try{await Trails.remove('trails',$('trailId').value);$('editor').close();await reload();status('Trail deleted.');}catch(e){$('formError').textContent=e.message;}};
let lastGeocode=0;
$('locateBtn').onclick=async()=>{const b=$('locateBtn');if(Date.now()-lastGeocode<1500)return;lastGeocode=Date.now();b.disabled=true;$('geocodeResults').textContent='Searching…';try{const query=[$('address').value||$('trailName').value,$('trailCity').value].filter(Boolean).join(', ');if(!query)throw Error('Enter a trail name and city first.');const r=await fetch('https://nominatim.openstreetmap.org/search?format=json&limit=4&q='+encodeURIComponent(query),{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('Search unavailable. Add coordinates manually.');const data=await r.json();$('geocodeResults').replaceChildren();if(!data.length)$('geocodeResults').textContent='No results. Try a more specific trailhead address, or enter coordinates.';for(const p of data){const btn=document.createElement('button');btn.type='button';btn.className='geocode-option';btn.textContent=p.display_name;btn.onclick=()=>{$('lat').value=p.lat;$('lon').value=p.lon;$('geocodeResults').textContent='Pin selected. Confirm this is the correct trailhead before saving.';};$('geocodeResults').append(btn);}}catch(e){$('geocodeResults').textContent=e.message;}finally{b.disabled=false;}};
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function updateStorage(){const persist=await navigator.storage?.persisted?.().catch(()=>false);$('storageStatus').textContent=persist?'Persistent storage granted. Still keep backups.':'Browser-managed local storage. Keep regular backups.';const d=await Trails.get('settings','lastBackup');$('backupDate').textContent=d?'Last backup exported: '+new Date(d.at).toLocaleString():'No backup exported on this device yet.';}
$('settingsBtn').onclick=async()=>{$('settings').showModal();try{const c=await Trails.get('settings','github');$('repo').value=c?.repo||'asre1212/Hiking-Trails';$('branch').value=c?.branch||'main';$('token').value='';$('token').placeholder=c?.token?'Token saved locally; leave blank to keep':'Contents: Read and write · only this repository';await updateStorage();}catch(e){settingsStatus(e.message);}};
$('persistBtn').onclick=async()=>{try{const ok=await navigator.storage?.persist?.();settingsStatus(ok?'Persistent storage enabled.':'Browser did not grant persistence. Keep backups.');await updateStorage();}catch(e){settingsStatus(e.message);}};
$('backupBtn').onclick=async()=>{const b=$('backupBtn');b.disabled=true;try{const data=await Trails.backup($('backupPassword').value);download(`hiking-trails-${new Date().toISOString().slice(0,10)}.json`,data);await Trails.write('settings',[{id:'lastBackup',at:new Date().toISOString()}]);$('backupPassword').value='';settingsStatus('Backup exported. Keep the file and password for your new phone.');await updateStorage();}catch(e){settingsStatus(e.message);}finally{b.disabled=false;}};
$('restoreBtn').onclick=()=>$('backupFile').click();
$('backupFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>30000000)throw Error('Backup is too large.');if(!$('backupPassword').value)throw Error('Enter the backup password before importing.');if(!confirm('Merge backup trails by ID and restore its delivery identity? Matching trail IDs are replaced. Reconnect GitHub afterward.'))return;const n=await Trails.restore(JSON.parse(await f.text()),$('backupPassword').value);$('backupPassword').value='';await Trails.remove('settings','github');$('token').value='';await reload();settingsStatus(`${n} trails restored. Reconnect GitHub on this phone; disconnect it on your old phone.`);}catch(e){settingsStatus(e.message);}finally{e.target.value='';}};
$('githubForm').onsubmit=async e=>{e.preventDefault();try{const old=await Trails.get('settings','github'),token=$('token').value.trim()||old?.token;if(!token)throw Error('Enter a fine-grained token scoped to this repository.');const config={id:'github',repo:$('repo').value.trim(),branch:$('branch').value.trim(),token};settingsStatus('Pairing this device with GitHub…');try{await Trails.pairInbox(config);}catch(err){if(err.code!=='OTHER_DEVICE')throw err;if(!confirm('Another device is paired. Replace its public key with this device? Disconnect the old phone first. Existing queued deliveries for the old key will not decrypt here.'))return;await Trails.pairInbox(config,true);}await Trails.write('settings',[config]);$('token').value='';settingsStatus('Device paired. Checking encrypted deliveries…');await sync();settingsStatus($('status').textContent);}catch(e){settingsStatus(e.message);}};
$('disconnectBtn').onclick=async()=>{await Trails.remove('settings','github');$('token').value='';settingsStatus('GitHub connection removed from this device.');};
$('publicKeyBtn').onclick=async()=>{try{const k=await Trails.keys();download('delivery-key.json',{type:'hiking-trails-public-key',version:1,publicKey:k.publicKey});settingsStatus('Public key exported. Commit only delivery-key.json to GitHub.');}catch(e){settingsStatus(e.message);}};
$('deliveryBtn').onclick=()=>$('deliveryFile').click();$('deliveryFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error('Delivery is too large.');const text=await f.text(),hash=Trails.b64(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)));const n=await Trails.ingest(await Trails.decryptDelivery(JSON.parse(text)),'file:'+hash);await reload();settingsStatus(`${n} trails imported locally. The selected file stays in your Files app until you delete it.`);}catch(e){settingsStatus('Import failed: '+e.message);}finally{e.target.value='';}};
async function sync(){if(syncing)return;syncing=true;$('syncBtn').disabled=true;status('Checking encrypted deliveries…');try{let result;const worker=registration?.active;if(worker){const channel=new MessageChannel();result=await new Promise((res,rej)=>{const timer=setTimeout(()=>rej(Error('Delivery check is still running. Reopen the app or check again.')),90000);channel.port1.onmessage=e=>{clearTimeout(timer);e.data.error?rej(Error(e.data.error)):res(e.data.result);};worker.postMessage({type:'SYNC_INBOX'},[channel.port2]);});}else result=await Trails.syncInbox();status(result.message+(result.errors?.length?'\n'+result.errors.join('\n'):''));await reload();if(result.errors?.length)await registration?.sync?.register('hiking-inbox').catch(()=>{});}catch(e){status(e.message);await registration?.sync?.register('hiking-inbox').catch(()=>{});}finally{syncing=false;$('syncBtn').disabled=false;}}
$('syncBtn').onclick=sync;
function online(){ $('onlineStatus').textContent=navigator.onLine?'Online':'Offline';if(!navigator.onLine)status('Offline. Your saved reviews are available; maps and delivery need internet.');}
window.addEventListener('online',()=>{online();sync();});window.addEventListener('offline',online);document.addEventListener('visibilitychange',()=>{if(!document.hidden)sync();});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('installBtn').hidden=false;});$('installBtn').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('installBtn').hidden=true;}};
(async()=>{try{await reload();online();if('serviceWorker'in navigator){try{registration=await navigator.serviceWorker.register('./sw.js');const installing=registration.installing||registration.waiting;if(installing&&installing.state!=='activated')await new Promise(resolve=>{installing.addEventListener('statechange',()=>{if(['activated','redundant'].includes(installing.state))resolve();});});registration=await navigator.serviceWorker.ready;navigator.serviceWorker.addEventListener('message',async e=>{if(e.data?.type==='SYNC_RESULT'){await reload();if(!syncing)status(e.data.result.message);}});}catch{status('Offline cache unavailable in this browser. Local reviews still save.');}}await importLink();if((await Trails.get('settings','github'))?.token)await sync();}catch(e){status('Local storage could not open. Enable website storage and reload. '+e.message);$('addBtn').disabled=true;}})();
